diff --git a/AGENTS.md b/AGENTS.md
index 7e4e775f7..73674bbe6 100644
--- a/AGENTS.md
+++ b/AGENTS.md
@@ -167,7 +167,14 @@ factual: paths, commands, invariants — no essays.
   `agent_cli_prompt.dart`; interactive modes never carry it) — before any
   final summary the agent re-quotes every explicit requirement as a
   checklist, verifies each item with a real command against the produced
-  state, and fixes or explicitly reports every unmet item. The loop parses
+  state, and fixes every unmet item. A final answer that still carries
+  unmet items is budget-conditional (gh-1646): compliant only when the
+  wall clock is effectively reached or every unmet item names a blocker
+  the agent cannot change — an honest ledger is not an early-exit
+  license. Step 2.5 (gh-1652) re-runs each produced entry point the way
+  the grader will — neutral cwd, fresh subprocess, clean env — so the
+  ledger's oracle is the verifier's own invocation, not the agent's
+  checklist. The loop parses
   the final answer's `task-ledger` fenced block (`parseTaskLedger`,
   last block wins) and emits `TaskLedgerEvent`; hosts persist the hidden
   `task_ledger` custom record (CLI: `agent_event_handler.dart` →
diff --git a/lib/src/agent/finalize_gate.dart b/lib/src/agent/finalize_gate.dart
index c54442e8f..ea4a443aa 100644
--- a/lib/src/agent/finalize_gate.dart
+++ b/lib/src/agent/finalize_gate.dart
@@ -8,8 +8,14 @@
 ///   `prompts/cli/finalize_gate.md`, rendered by the hosts into the system
 ///   prompt). Before any final summary the agent re-quotes every explicit
 ///   requirement as a checklist, verifies each item with a real command
-///   against the produced state, and fixes or explicitly reports every
-///   unmet item.
+///   against the produced state, and fixes every unmet item. A final
+///   answer that still carries unmet items is budget-conditional (gh-1646):
+///   compliant only when the wall clock is effectively reached or every
+///   unmet item names a blocker the agent cannot change — an honest
+///   ledger is not an early-exit license. Step 2.5 (gh-1652) re-runs each
+///   produced entry point the way the grader will — neutral cwd, fresh
+///   subprocess, clean env — so the ledger's oracle is the verifier's
+///   own invocation, not the agent's checklist.
 /// - **TaskLedger** — the checklist itself as a hidden session record
 ///   (`task_ledger` custom record, shaped like `model_request_summary`):
 ///   post-mortems see WHAT was self-checked, the bench summary reports
diff --git a/lib/src/session_deadline.dart b/lib/src/session_deadline.dart
index 0cbc41284..a354bc7fd 100644
--- a/lib/src/session_deadline.dart
+++ b/lib/src/session_deadline.dart
@@ -84,7 +84,10 @@ final class DeadlineLadder {
   /// The steering text for [kind], rendered with the current [timeLeft]
   /// (`formatTimeLeft` spelling). The T-3min steer names the
   /// shell-job/background-work drain explicitly — long-running operations
-  /// must get their chance to land instead of being SIGKILLed mid-write.
+  /// must get their chance to land instead of being SIGKILLed mid-write —
+  /// and the grader-parity clause (gh-1652): the LAST verification pass
+  /// before finalizing goes through the grader's own invocation path,
+  /// not the agent's checklist oracle.
   String text(DeadlineNoticeKind kind, String timeLeft) => switch (kind) {
     DeadlineNoticeKind.halfBudget =>
       'Half of your time budget has elapsed ($timeLeft remaining). '
@@ -94,7 +97,9 @@ final class DeadlineLadder {
           'NOW: drain or kill background shell jobs (`bash_job stop <id>`) '
           'and any in-flight subagents so long-running operations '
           '(compiles, uploads, file writes) get their chance to land, run '
-          'your final checks, and write your final answer.',
+          'your final checks, and before finalizing run each produced '
+          'entry point the way the grader will (neutral cwd, clean env) '
+          'and fix what diverges. Then write your final answer.',
     DeadlineNoticeKind.finalAnswer =>
       '$timeLeft remaining — write your final answer NOW.',
   };
@@ -193,8 +198,10 @@ String formatTimeLeft(int remainingMs) {
 final class SessionDeadline {
   /// Creates a clock. [clock] defaults to [DateTime.now]; tests inject a
   /// fake. [ladder] defaults to the standard T-3min/T-30s windows.
-  SessionDeadline({DateTime Function()? clock, this.ladder = const DeadlineLadder()})
-    : _clock = clock ?? DateTime.now;
+  SessionDeadline({
+    DateTime Function()? clock,
+    this.ladder = const DeadlineLadder(),
+  }) : _clock = clock ?? DateTime.now;

   /// The injected wall clock.
   final DateTime Function() _clock;
